BasicProperties.ActionCode:
f_setPVSystemCompanies( uI_Tabs.f_getActiveSliderGridConnections_utilities(), sl_companiesRooftopPV_pct.getValue(), sl_companiesRooftopPV_pct );

//If on pv map overlay, adjust colouring
if(zero_Interface.v_activeMapOverlay == OL_MapOverlayTypes.PV_PRODUCTION){
	zero_Interface.f_setMapOverlay();
}

f_setPVSystemHouses( uI_Tabs.f_getActiveSliderGridConnections_houses(), sl_householdRooftopPV_pct.getValue() );

//If on pv map overlay, adjust colouring
if(zero_Interface.v_activeMapOverlay == OL_MapOverlayTypes.PV_PRODUCTION){
	zero_Interface.f_setMapOverlay_PVProduction();
}

// Also updates the home batteries
f_setHouseholdBatteries( sl_householdBatteries_pct.getValue(), uI_Tabs.f_getActiveSliderGridConnections_houses() );

for (GridNode GN : zero_Interface.energyModel.pop_gridNodes){
	GN.p_capacity_kW = GN.p_originalCapacity_kW;
}
zero_Interface.f_setSelectedGNText();

List<GCGridBattery> gcListGridBatteries = new ArrayList<>();
for(GridConnection gc : c_electricityTabEASliderGCs){
	if(gc instanceof GCGridBattery gridbattery){
		gcListGridBatteries.add(gridbattery);
	}
}

double totalCustomBatteryCapacity_MWh = 0;
for(GridConnection customGB : c_customGridBatteryGCs){
	if(customGB.v_isActive && customGB.p_batteryAsset != null){
		totalCustomBatteryCapacity_MWh += customGB.p_batteryAsset.getStorageCapacity_kWh()/1000;
	}
}

f_setGridBatteries((sl_gridBatteries_MWh.getValue() - totalCustomBatteryCapacity_MWh - p_initialTotalGridBatteryCapacity_MWh)*1000.0, gcListGridBatteries);

// 1. Construct list containing ONLY the default global solarfarms (excluding custom ones)
List<GCEnergyProduction> sliderPVFarmGCList = new ArrayList<>();
for(GridConnection gc : c_electricityTabEASliderGCs){
	if(gc instanceof GCEnergyProduction energyProductionSite){
		for(J_EAProduction j_ea : energyProductionSite.c_productionAssets) {
			if (j_ea.getEAType() == OL_EnergyAssetType.PHOTOVOLTAIC) {
				sliderPVFarmGCList.add(energyProductionSite);
				break;
			}
		}
	}
}

if(sliderPVFarmGCList.size() == 0){
	throw new IllegalStateException("Model does not contain any PVFarmSliderGC agent");
}

// 2. Calculate sum of active custom solarfarms capacity
double totalCustomPVOnLand_kW = 0;
for(GridConnection customSF : c_customSolarfarmGCs){
    if(customSF.v_isActive){
        for(J_EAProduction ea : customSF.c_productionAssets){
            if(ea.getEAType() == OL_EnergyAssetType.PHOTOVOLTAIC){
                totalCustomPVOnLand_kW += ea.getCapacityElectric_kW();
            }
        }
    }
}

f_setPVOnLand(sl_largeScalePV_ha.getValue() - p_initialPVOnLand_ha - totalCustomPVOnLand_kW/zero_Interface.energyModel.avgc_data.p_avgSolarFieldPower_kWppha, sliderPVFarmGCList);

// 1. Construct list containing ONLY the default global windfarms (excluding custom ones)
List<GCEnergyProduction> sliderWindFarmGCList = new ArrayList<>();
for(GridConnection gc : c_electricityTabEASliderGCs){
	if(gc instanceof GCEnergyProduction energyProductionSite){
		for(J_EAProduction j_ea : energyProductionSite.c_productionAssets) {
			if (j_ea.getEAType() == OL_EnergyAssetType.WINDMILL) {
				sliderWindFarmGCList.add(energyProductionSite);
				break;
			}
		}
	}
}

if(sliderWindFarmGCList.size() == 0){
	throw new IllegalStateException("Model does not contain any sliderWindFarmGC agent");
}

// 2. Calculate sum of active custom solarfarms capacity
double totalCustomWind_kW = 0;
for(GridConnection customWF : c_customWindfarmGCs){
    if(customWF.v_isActive){
        for(J_EAProduction ea : customWF.c_productionAssets){
            if(ea.getEAType() == OL_EnergyAssetType.WINDMILL){
                totalCustomWind_kW += ea.getCapacityElectric_kW();
            }
        }
    }
}

f_setWindTurbines( sl_largeScaleWind_MW.getValue() - p_initialWindTurbines_MW - totalCustomWind_kW/1000, sliderWindFarmGCList);

Group.OnClickCode:
if(!c_customSolarfarmGCs.isEmpty() || !c_customWindfarmGCs.isEmpty() || !c_customGridBatteryGCs.isEmpty()) {
	uI_Tabs.zero_Interface.v_currentUIMode = OL_UIMode.REMOVE_CUSTOMGC;
	zero_Interface.f_setForcedClickScreenTextBoxes("ENERGIEASSETS VERWIJDEREN", (Color)teal, null, "Kies een energieasset op de kaart", new Color(148, 215, 209), null);
	zero_Interface.f_setForcedClickScreenVisibility(true);
} else {
	throw new RuntimeException("There is no custom energy asset loaded in.");
}

RoundedRectangle.OnClickCode:
if(!c_customSolarfarmGCs.isEmpty() || !c_customWindfarmGCs.isEmpty() || !c_customGridBatteryGCs.isEmpty()) {
	uI_Tabs.zero_Interface.v_currentUIMode = OL_UIMode.REMOVE_CUSTOMGC;
	zero_Interface.f_setForcedClickScreenTextBoxes("Energieassets verwijderen", new Color(255, 255, 255), new Color(0, 0, 0), "Kies een energieasset op de kaart", new Color(255, 255, 255), new Color(0, 0, 0));
	zero_Interface.f_setForcedClickScreenVisibility(true);
} else {
	throw new RuntimeException("There is no custom energy asset loaded in.");
}

Group.OnClickCode:
zero_Interface.v_currentUIMode = OL_UIMode.ADD_CUSTOMGC;
v_addCustomGCType = OL_EnergyAssetType.PHOTOVOLTAIC;
zero_Interface.f_setForcedClickScreenTextBoxes("ENERGIEASSETS TOEVOEGEN", (Color)teal, null, "Teken je locatie op de kaart. Kies nog minimaal 3 hoekpunten.", new Color(148, 215, 209), null);
zero_Interface.f_setForcedClickScreenVisibility(true);

zero_Interface.v_currentUIMode = OL_UIMode.ADD_CUSTOMGC;
v_addCustomGCType = OL_EnergyAssetType.WINDMILL;
zero_Interface.f_setForcedClickScreenTextBoxes("ENERGIEASSETS TOEVOEGEN", (Color)teal, null, "Kies een locatie op de kaart", new Color(148, 215, 209), null);
zero_Interface.f_setForcedClickScreenVisibility(true);

zero_Interface.v_currentUIMode = OL_UIMode.ADD_CUSTOMGC;
v_addCustomGCType = OL_EnergyAssetType.STORAGE_ELECTRIC;
zero_Interface.f_setForcedClickScreenTextBoxes("ENERGIEASSETS TOEVOEGEN", (Color)teal, null, "Kies een locatie op de kaart", new Color(148, 215, 209), null);
zero_Interface.f_setForcedClickScreenVisibility(true);

BasicProperties.ActionCode:
double installedCapacity_kWpha = sl_customGCSolarfarmInstalledCapacity_kWpha.getValue();

GCEnergyProduction gc = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
J_EAProduction pvAsset = (J_EAProduction)gc.c_productionAssets.get(0);

// Calculate new installed capacity solarfarm and update text objects
double area_m2 = gc.c_connectedGISObjects.get(0).gisRegion.area();
double area_ha = area_m2 / 10000.0;
double installedCapacity_kW = installedCapacity_kWpha * area_ha;

// Calculate max contracted range to be the next multiple of 10 kW above installed capacity
double maxContractedCapacity_kW = ceil(installedCapacity_kW / 10.0) * 10.0;

// Dynamically clamp the range of the contracted capacity slider
sl_customGCSolarfarmContractedCapacity_kW.setRange(0, maxContractedCapacity_kW);
sl_customGCSolarfarmContractedCapacity_kW.setValue(maxContractedCapacity_kW, false);

// Update backend
pvAsset.setCapacityElectric_kW(installedCapacity_kW, gc);
gc.v_liveConnectionMetaData.setCapacities_kW(0, maxContractedCapacity_kW, maxContractedCapacity_kW);

// Update the active instance of tabElectricity sliders
f_updateSliders_Electricity();

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

GCEnergyProduction gc = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
if (cb_customGCSolarfarmCurtailment.isSelected()) {
    gc.f_setExternalAssetManagement(new J_CurtailManagementContractCapacity(gc, zero_Interface.energyModel.p_timeParameters));
} else {
    gc.f_removeExternalAssetManagement(I_CurtailManagement.class);
}

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

GCEnergyProduction gc = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
double physicalCapacity_kW = gc.v_liveConnectionMetaData.getPhysicalCapacity_kW();

double contractedCapacity_kW = sl_customGCSolarfarmContractedCapacity_kW.getValue();

gc.v_liveConnectionMetaData.setCapacities_kW(0, contractedCapacity_kW, physicalCapacity_kW);

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

GCEnergyProduction solarpark = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
J_EAProduction pvAsset = (J_EAProduction) solarpark.c_productionAssets.get(0);
J_ProfilePointer profile;
OL_PVOrientation pvOrientation;

switch(cb_customGCSolarfarmPVOrientation.getValue()){
	case "Zuid (15°)":
    	profile = zero_Interface.energyModel.pp_PVProduction35DegSouth_fr;
        pvOrientation = OL_PVOrientation.SOUTH;
		break;
	case "Oost/West (35°)":
    	profile = zero_Interface.energyModel.pp_PVProduction15DegEastWest_fr;
        pvOrientation = OL_PVOrientation.EASTWEST;
        break;
    default:
        return;
}

double installedCapacity_kW = pvAsset.getCapacityElectric_kW();
pvAsset.removeEnergyAsset();
new J_EAProduction(solarpark, OL_EnergyAssetType.PHOTOVOLTAIC, "Custom PV", OL_EnergyCarriers.ELECTRICITY, installedCapacity_kW, zero_Interface.energyModel.p_timeParameters, profile);
solarpark.v_liveAssetsMetaData.PVOrientation = pvOrientation;

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

double installedCapacity_MW = sl_customGCWindfarmInstalledCapacity_MW.getValue();

GCEnergyProduction gc = (GCEnergyProduction)(zero_Interface.c_selectedGridConnections).get(0);
J_EAProduction windAsset = (J_EAProduction)gc.c_productionAssets.get(0);

// Dynamically clamp the range of the contracted capacity slider
sl_customGCWindfarmContractedCapacity_MW.setRange(0, installedCapacity_MW + 1E-10);
sl_customGCWindfarmContractedCapacity_MW.setValue(installedCapacity_MW, false);

// Update backend
windAsset.setCapacityElectric_kW(installedCapacity_MW*1000, gc);
gc.v_liveConnectionMetaData.setCapacities_kW(0, installedCapacity_MW*1000, installedCapacity_MW*1000);

// Update the active instance of tabElectricity sliders
f_updateSliders_Electricity();

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

GCEnergyProduction gc = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
if (cb_customGCWindfarmCurtailment.isSelected()) {
    gc.f_setExternalAssetManagement(new J_CurtailManagementContractCapacity(gc, zero_Interface.energyModel.p_timeParameters));
} else {
    gc.f_removeExternalAssetManagement(I_CurtailManagement.class);
}

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

double contractedCapacity_MW = sl_customGCWindfarmContractedCapacity_MW.getValue();

// Update backend
GCEnergyProduction gc = (GCEnergyProduction) (zero_Interface.c_selectedGridConnections).get(0);
gc.v_liveConnectionMetaData.setCapacities_kW(0, contractedCapacity_MW*1000, gc.v_liveConnectionMetaData.getPhysicalCapacity_kW());

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

double installedCapacity_MWh = sl_customGCGridBatteryInstalledCapacity_MWh.getValue();
double installedCapacity_MW = installedCapacity_MWh / zero_Interface.energyModel.avgc_data.p_avgRatioBatteryCapacity_v_Power;

sl_customGCGridBatteryInstalledCapacity_MW.setRange(0.05, installedCapacity_MW + 1E-10);
sl_customGCGridBatteryInstalledCapacity_MW.setValue(installedCapacity_MW, false);

GCGridBattery gc = (GCGridBattery)(zero_Interface.c_selectedGridConnections).get(0);
J_EAStorageElectric batteryAsset = (J_EAStorageElectric)gc.c_storageAssets.get(0);

// Update backend
batteryAsset.setStorageCapacity_kWh(installedCapacity_MWh * 1000, gc);
batteryAsset.setCapacityElectric_kW(installedCapacity_MW * 1000);
gc.v_liveConnectionMetaData.setCapacities_kW(installedCapacity_MW * 1000, installedCapacity_MW * 1000, installedCapacity_MW * 1000);

// Update the active instance of tabElectricity sliders
f_updateSliders_Electricity();

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

double installedCapacity_MW = sl_customGCGridBatteryInstalledCapacity_MW.getValue();
double installedCapacity_kW = installedCapacity_MW * 1000;

GCGridBattery gc = (GCGridBattery)(zero_Interface.c_selectedGridConnections).get(0);
J_EAStorageElectric batteryAsset = (J_EAStorageElectric)gc.c_storageAssets.get(0);

batteryAsset.setCapacityElectric_kW(installedCapacity_kW);
gc.v_liveConnectionMetaData.setCapacities_kW(installedCapacity_kW, installedCapacity_kW, installedCapacity_kW);

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();

if (zero_Interface.c_selectedGridConnections.isEmpty() || !(zero_Interface.c_selectedGridConnections.get(0) instanceof GCGridBattery)) {
    return;
}
GCGridBattery gc = (GCGridBattery)(zero_Interface.c_selectedGridConnections).get(0);
GridNode gn = gc.p_parentNodeElectric;
I_BatteryManagement batteryAlgorithm = null;

switch(cb_customGCGridBatteryAlgorithm.getValue()){
	case "Zelfverbruik":
    	batteryAlgorithm = new J_BatteryManagementSelfConsumptionGridNode(gc, zero_Interface.energyModel.p_timeParameters);
    	break;
	case "Peak shaving":
    	batteryAlgorithm = new J_BatteryManagementPeakShaving(gc, zero_Interface.energyModel.p_timeParameters);
    	((J_BatteryManagementPeakShaving)batteryAlgorithm).setTarget(gn);
    	break;
	case "Prijssturing":
    	batteryAlgorithm = new J_BatteryManagementPrice(gc, zero_Interface.energyModel.p_timeParameters);
    	break;
}

gc.f_setBatteryManagement(batteryAlgorithm);

if (!zero_Interface.b_runningMainInterfaceScenarios) zero_Interface.f_setScenarioToCustom();
zero_Interface.f_resetSettings();
